/* Calm editorial system. Palette and existing screen structure are preserved. */
:root {
  --shadow: 0 12px 32px #3c30260a;
  --radius: 20px;
  --accent: #506a51;
}
body { background: var(--paper); font-size: 16px; }
::selection { background: var(--sage2); color: var(--ink); }
button, input, textarea, select { -webkit-tap-highlight-color: transparent; }
button { transition: background .18s, border-color .18s, box-shadow .18s, transform .18s; }
button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible, summary:focus-visible, a:focus-visible { outline: 3px solid var(--accent); outline-offset: 4px; }
button:disabled { cursor: not-allowed; opacity: .55; }
.topbar { background: #f7f2e8f5; border-bottom: 1px solid var(--line); }
.topbar-inner { max-width: 1240px; padding: 18px 32px; }
.brand { display: flex; align-items: center; gap: 13px; border: 0; padding: 0; background: none; color: var(--ink); text-align: left; font-size: 24px; line-height: 1.2; }
.brand small { display: block; font: 11px var(--sans); color: var(--muted); margin-top: 7px; letter-spacing: .035em; }
.brand-mark { display: grid; place-items: center; width: 45px; height: 51px; border: 1px solid var(--gold); border-radius: 24px 24px 8px 8px; color: #8d7655; font-size: 31px; background: var(--paper2); }
.top-actions { align-items: center; gap: 16px; }
.icon-btn { background: var(--paper2); border-radius: 50%; box-shadow: none; }
.icon-btn:hover { background: var(--sage2); }
.privacy-badge { background: transparent; font-size: 12px; }
main { max-width: 1240px; padding: 32px 32px 140px; }
h1, h2, h3 { letter-spacing: -.035em; text-wrap: balance; }
h2 { font-size: clamp(32px, 3.5vw, 46px); }
p { line-height: 1.75; }
.eyebrow { font-size: 11px; letter-spacing: .14em; color: #796344; }
.view > .eyebrow { display: block; margin: 15px 0; }
.view > .muted { max-width: 650px; }
.hero { position: relative; grid-template-columns: 1.2fr 1fr; gap: 24px; align-items: center; padding: 44px; margin: 0 0 44px; background: var(--paper2); border: 1px solid var(--line); border-radius: 28px; overflow: hidden; }
.hero-copy { position: relative; z-index: 1; padding: 0; background: none; border: 0; box-shadow: none; }
.hero-copy .eyebrow { display: flex; align-items: center; gap: 12px; }
.hero-copy .eyebrow::before { content: ''; width: 25px; height: 1px; background: var(--gold); }
.hero h1 { font-size: clamp(44px, 5.3vw, 72px); line-height: 1.05; margin: 26px 0 22px; }
.hero h1 em { font-weight: 400; color: var(--accent); }
.hero-copy p { max-width: 470px; color: var(--muted); font-size: 16px; margin-bottom: 28px; }
.hero-copy .btn-row { gap: 12px; }
.btn { min-height: 46px; border: 1px solid transparent; border-radius: 12px; padding: 12px 19px; font-size: 14px; font-weight: 600; background: var(--accent); color: var(--paper2); box-shadow: none; }
.btn:hover { transform: translateY(-2px); box-shadow: 0 6px 16px #3c302614; }
.btn.secondary { background: var(--paper2); border: 1px solid var(--line); color: var(--ink); }
.btn.secondary:hover { background: var(--paper); border-color: var(--gold); }
.btn.ghost { border-color: transparent; background: transparent; color: var(--accent); }
.btn.blue { background: #dfe8ef; color: #425c70; }
.btn.gold { background: #d7bc87; color: var(--ink); }
.hero-art { min-height: 400px; display: flex; align-items: center; justify-content: center; padding: 26px 16px 48px; background: none; overflow: visible; }
.hero-art::after { display: none; }
.hero-orbit { position: absolute; width: 100%; max-width: 360px; aspect-ratio: 1; background: var(--sage2); border-radius: 50% 50% 44% 56%; transform: rotate(-12deg); }
.hero-orbit::after { content: ''; position: absolute; inset: -18px; border: 1px solid var(--line); border-radius: 50%; }
.hero-art img { position: relative; width: 225px; height: auto; aspect-ratio: 5/7; object-fit: contain; opacity: 1; transform: rotate(8deg); border: 7px solid var(--paper2); border-radius: 12px; box-shadow: -15px 15px 0 -5px #e8decc, -15px 15px 0 -4px var(--line), 0 22px 32px #3c30261c; }
.art-caption { position: absolute; bottom: 0; color: var(--muted); font: italic 14px var(--serif); text-align: center; }
.hero-footnote { display: flex; align-items: center; gap: 8px; margin-top: 22px; font-size: 12px; color: var(--muted); }
.hero-footnote::before { content: ''; width: 6px; height: 6px; background: var(--sage); border-radius: 50%; }
.section-title { margin: 32px 0 20px; }
.practice-heading { margin-top: 0; }
.practice-heading h2 { margin: 8px 0 0; }
.practice-heading > .muted { font-size: 13px; }
.quick-grid { counter-reset: practice; gap: 16px; margin: 22px 0 42px; }
.quick { position: relative; counter-increment: practice; min-height: 205px; padding: 24px; border: 1px solid var(--line); border-radius: 18px; background: var(--paper2); box-shadow: none; }
.quick::before { content: '0' counter(practice); display: block; font: italic 19px var(--serif); color: var(--muted); margin-bottom: 34px; }
.quick::after { content: '↗'; position: absolute; top: 20px; right: 20px; width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid #3c302622; border-radius: 50%; }
.quick .emoji { display: none; }
.quick strong { font-size: 24px; line-height: 1.15; min-height: 55px; }
.quick small { display: block; margin-top: 15px; font-size: 12px; }
.quick.sage { background: var(--sage2); border-color: #8fa38d55; }
.quick.blue { background: #e7edf1; border-color: #b8c8d588; }
.quick.lilac { background: #f1e7e3; border-color: #d9a99a66; }
.quick:hover { transform: translateY(-4px); box-shadow: var(--shadow); border-color: var(--gold); }
.panel, .soft-panel { box-shadow: none; background: var(--paper2); border-color: var(--line); }
.hero-copy { background: none; border: 0; }
.card-day { grid-template-columns: 150px 1fr; padding: 30px; gap: 32px; background: linear-gradient(110deg, var(--sage2), var(--paper2) 65%); border-radius: 22px; }
.card-day h3 { font-size: 32px; }
.card-day .thumb-card { border: 5px solid var(--paper2); border-radius: 12px; box-shadow: 0 8px 24px #3c30261a; }
.card-day .muted { max-width: 600px; }
.link-btn { font-size: 14px; min-height: 44px; }
.privacy-strip { background: transparent; border-top: 1px solid var(--line); border-radius: 0; padding: 24px 0 0; font-size: 13px; }
.bottom-nav { left: 50%; right: auto; bottom: 20px; transform: translateX(-50%); width: min(640px, calc(100% - 32px)); padding: 7px; border: 1px solid var(--line); border-radius: 22px; box-shadow: 0 12px 40px #3c30261a; }
.bottom-inner { gap: 5px; }
.nav-btn { border-radius: 15px; padding: 9px 6px; min-height: 60px; font-size: 12px; }
.nav-btn .nav-ico { font-size: 21px; line-height: 1.3; margin-bottom: 4px; }
.nav-btn.active { background: var(--sage2); color: #3c503d; }
.nav-btn:hover { background: #eee9df; }
.nav-btn.active:hover { background: var(--sage2); }
.state-grid, .sections-grid, .scenario-grid { gap: 20px; margin-top: 30px; }
.state-btn, .section-card, .scenario { background: var(--paper2); border-radius: 18px; padding: 26px; border-color: var(--line); }
.state-btn:hover, .section-card:hover, .scenario:hover { transform: translateY(-3px); border-color: var(--sage); box-shadow: var(--shadow); }
.state-btn strong { font-family: var(--serif); font-size: 22px; font-weight: 400; }
.scenario { display: flex; flex-direction: column; align-items: flex-start; border-top: 3px solid var(--sage); }
.scenario:nth-child(3n + 2) { border-top-color: var(--gold); }
.scenario:nth-child(3n) { border-top-color: var(--rose); }
.scenario .time { background: var(--paper); font-size: 12px; }
.scenario h3 { font-size: 28px; margin-top: 24px; }
.scenario p { font-size: 14px; color: var(--muted); }
.scenario-cue { display: block; margin-top: auto; padding-top: 18px; font-size: 13px; color: var(--accent); }
.flow-slot { background: var(--paper2); border-radius: 18px; }
.deck-grid { gap: 26px 20px; margin-top: 20px; }
.deck-item { padding: 10px 10px 18px; background: var(--paper2); border: 1px solid var(--line); border-radius: 16px; transition: transform .2s, box-shadow .2s; }
.deck-item img { display: block; border-radius: 9px; box-shadow: none; }
.deck-item strong { font-family: var(--serif); font-size: 18px; font-weight: 400; line-height: 1.3; margin: 14px 3px 0; }
.deck-item:hover { transform: translateY(-4px); box-shadow: var(--shadow); border-color: var(--gold); }
.search { color: var(--ink); padding: 15px 18px; border-radius: 12px; }
.filter-row { flex-wrap: wrap; overflow: visible; gap: 8px; padding: 8px 0 18px; }
.chip, .tab { font-size: 13px; min-height: 44px; }
.chip { white-space: normal; text-align: left; background: transparent; }
.chip.on { background: var(--sage2); border-color: var(--sage); }
.deck-status { display: flex; justify-content: space-between; align-items: center; gap: 12px; border-top: 1px solid var(--line); padding-top: 14px; font-size: 13px; color: var(--muted); }
.back-link { min-height: 44px; font-size: 14px; margin-bottom: 14px; }
.story-stage { max-width: 740px; }
.big-card, .story-cover { box-shadow: 0 12px 28px #3c30261a; border-radius: 16px; }
.story-content { background: var(--paper2); box-shadow: none; border-color: var(--line); }
.story-paper { border-color: var(--line); }
.card-meta { padding-top: 16px; }
.card-meta h2 { font-size: clamp(30px, 4vw, 44px); }
.question-box { background: var(--sage2); border: 0; border-left: 3px solid var(--sage); border-radius: 0 18px 18px 0; padding: 26px; margin: 24px 0; }
.question-box p { margin-top: 10px; line-height: 1.5; font-size: 25px; }
.save-panel { padding: 26px; background: var(--paper2); border-radius: 18px; margin-top: 26px; }
.note-area { border-radius: 12px; background: var(--paper); min-height: 180px; }
.tabs { gap: 8px; padding-bottom: 20px; flex-wrap: wrap; }
.tab { background: transparent; border: 1px solid var(--line); }
.tab.on { background: var(--accent); border-color: var(--accent); }
.note-card { padding: 24px; border-radius: 18px; background: var(--paper2); gap: 22px; }
.note-card h3 { font-size: 26px; }
.note-actions { display: flex; flex-direction: column; gap: 8px; }
.empty { border: 1px dashed var(--line); border-radius: 18px; background: var(--paper2); margin-top: 18px; padding: 48px 24px; }
.empty strong { display: block; font: 28px var(--serif); color: var(--ink); margin-bottom: 10px; }
details { background: var(--paper2); border-radius: 16px; margin: 14px 0; }
summary { padding: 25px; font-size: 24px; }
.details-body { padding: 0 25px 25px; max-width: 850px; }
.method-hero { border-left: 4px solid var(--sage); margin: 26px 0; }
.method-hero p { max-width: 800px; }
.modal { align-items: center; background: #3c302655; backdrop-filter: blur(6px); }
.sheet { border-radius: 24px; padding: 30px; box-shadow: 0 24px 80px #3c302633; }
.settings-sheet { overflow-y: auto; }
.settings-section-label { color: var(--accent); }
.settings-close { min-width: 44px; min-height: 44px; }
.settings-action-btn { min-height: 100px; }
.switch { border: 1px solid var(--line); }
.toast { bottom: 112px; max-width: calc(100% - 32px); width: max-content; text-align: center; font-size: 14px; }
.skip-link { position: fixed; left: 16px; top: -100px; z-index: 100; padding: 12px 20px; border-radius: 10px; background: var(--paper2); }
.skip-link:focus { top: 12px; }
@media (max-width: 1000px) {
  .hero { padding: 32px; gap: 20px; }
  .hero-art img { width: 190px; }
  .hero-orbit { max-width: 280px; }
  .hero-copy .btn-row { align-items: stretch; flex-direction: column; }
  .quick { padding: 20px; }
  .quick strong { font-size: 21px; }
  .scenario-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 700px) {
  .topbar-inner { padding: 15px 20px; }
  main { padding: 22px 20px 125px; }
  .hero { grid-template-columns: 1fr; padding: 28px; gap: 20px; }
  .hero-art { order: initial; min-height: 300px; }
  .hero-art img { width: 175px; }
  .hero-orbit { max-width: 240px; }
  .hero h1 { font-size: 52px; max-width: 480px; }
  .hero-copy p { max-width: none; }
  .hero-copy .btn-row { flex-direction: row; }
  .quick-grid { grid-template-columns: repeat(2, 1fr); }
  .quick strong { min-height: 48px; }
  .practice-heading > .muted { display: none; }
  .card-day { padding: 22px; gap: 22px; grid-template-columns: 110px 1fr; }
  .card-day h3 { font-size: 26px; }
  .state-grid { grid-template-columns: repeat(2, 1fr); }
  .note-card { grid-template-columns: 70px minmax(0, 1fr); padding: 18px; gap: 16px; }
  .note-card img { width: 70px; }
  .note-actions { grid-column: 1 / -1; flex-direction: row; flex-wrap: wrap; border-top: 1px solid var(--line); padding-top: 14px; }
}
@media (max-width: 480px) {
  .brand { font-size: 20px; gap: 10px; }
  .brand small { font-size: 9px; letter-spacing: 0; }
  .brand-mark { width: 35px; height: 43px; font-size: 27px; }
  .privacy-badge { display: none; }
  .topbar-inner { padding: 13px 16px; }
  main { padding: 16px 16px 118px; }
  .hero { padding: 24px 20px; border-radius: 22px; margin-bottom: 30px; }
  .hero h1 { font-size: clamp(38px, 11vw, 50px); }
  .hero-copy p { font-size: 14px; }
  .hero-copy .eyebrow { font-size: 9px; letter-spacing: .08em; }
  .hero-copy .btn-row { flex-direction: column; }
  .hero-art { min-height: 265px; padding-bottom: 30px; }
  .hero-art img { width: 150px; }
  .hero-orbit { max-width: 200px; }
  .art-caption { font-size: 12px; }
  .hero-footnote { font-size: 11px; }
  .quick-grid { gap: 12px; }
  .quick { padding: 17px; min-height: 190px; }
  .quick strong { font-size: 21px; }
  .quick::before { margin-bottom: 28px; }
  .quick::after { right: 13px; top: 13px; }
  .card-day { grid-template-columns: 85px minmax(0, 1fr); padding: 18px; gap: 18px; }
  .card-day h3 { font-size: 23px; }
  .card-day p { font-size: 13px; }
  .bottom-nav { bottom: 0; width: 100%; border-radius: 20px 20px 0 0; padding: 7px 5px calc(7px + env(safe-area-inset-bottom)); }
  .nav-btn { font-size: 10px; min-height: 57px; }
  .nav-btn .nav-ico { font-size: 20px; }
  .state-grid, .sections-grid, .scenario-grid { grid-template-columns: 1fr; gap: 14px; }
  .state-btn { min-height: 95px; }
  .state-btn span { display: inline-block; margin: 0 14px 0 0; }
  .deck-grid { gap: 14px 12px; }
  .deck-item { padding: 7px 7px 14px; }
  .deck-item strong { font-size: 17px; }
  .filter-row { gap: 6px; }
  .chip { font-size: 12px; padding: 9px 11px; }
  .save-panel, .question-box { padding: 20px; }
  .question-box p { font-size: 22px; }
  .settings-header, .settings-section { padding: 20px; }
  .settings-actions { grid-template-columns: 1fr; }
  .settings-section { flex-shrink: 0; }
  summary { font-size: 21px; padding: 20px; }
  .details-body { padding: 0 20px 20px; }
}
@media (prefers-reduced-motion: reduce) {
  button:hover, .deck-item:hover { transform: none; }
}
@media print { main { padding: 0; } .skip-link { display: none; } }
